{"content": "#!/usr/bin/env python3
"""Search derived_secret candidates for a captured alice:1337 session, no CSIDH needed.

Key insight: p = 419 (=4*3*5*7-1). Alice's derived_secret = csidh.action(A_B) is a
Montgomery A-coefficient in GF(p) of a curve in the supersingular isogeny class, i.e.
one of the few A in 0..418 with #E(Fp) = p+1 = 420 (twists included). So we can
enumerate A candidates directly and test PBKDF2+AES-GCM.
"""
import base64
import json
import os
import sys
from multiprocessing import Pool

from Crypto.Cipher import AES
from Crypto.Hash import SHA512
from Crypto.Protocol.KDF import PBKDF2
from Crypto.Util.number import long_to_bytes

P = 419


def curve_order(A):
    """#E(Fp) for y^2 = x^3 + A x^2 + x over F_p (p = 3 mod 4) by naive count."""
    # affine points: for each x, count roots of y^2 = x^3+A x^2+x  -> 1 + legendre
    total = 0
    for x in range(P):
        rhs = (x * x * x + A * x * x + x) % P
        if rhs == 0:
            total += 1
        else:
            leg = pow(rhs, (P - 1) // 2, P)
            if leg == 1:
                total += 2
    return total + 1  # point at infinity


def candidates(order_filter=True):
    out = []
    for A in range(P):
        if A in (2, P - 2):  # singular curves
            continue
        n = curve_order(A)
        if (not order_filter) or n == P + 1:
            out.append((A, n))
    return out


def try_A(args):
    A, nonce_b64, ct_b64, tag_b64 = args
    key = PBKDF2(long_to_bytes(A), b"secret_salt", count=1000000, hmac_hash_module=SHA512)
    try:
        pt = AES.new(key, AES.MODE_GCM, nonce=base64.b64decode(nonce_b64)).decrypt_and_verify(
            base64.b64decode(ct_b64), base64.b64decode(tag_b64)
        )
        return (A, pt)
    except ValueError:
        return (A, None)


def main():
    sess = json.loads(sys.argv[1])
    print("session:", sess, flush=True)
    if "--all" in sys.argv:
        cand = [A for A, n in candidates(order_filter=False)]
    else:
        cand = [A for A, n in candidates(order_filter=True)]
        print("curves with #E=420:", [(A, n) for A, n in candidates()], flush=True)
    print("trying %d candidate A values (p=%d)" % (len(cand), P), flush=True)
    work = [(A, sess["Nonce"], sess["CT"], sess["Tag"]) for A in cand]
    with Pool(min(len(work), os.cpu_count() or 4)) as pool:
        for A, pt in pool.imap_unordered(try_A, work):
            print("  A=%d -> %r" % (A, pt), flush=True)
            if pt is not None:
                print("FOUND derived_secret A =", A, "plaintext =", pt, flush=True)
                pool.terminate()
                return


if __name__ == "__main__":
    main()
